-- GENERATED by tools/sync_server_rules.py from main/data/star_systems.lua - edit that file, not this copy.
-- The Verge's star-system map. Topology (positions, sizes, the two
-- faction-locked home systems, and the threat-rating concept) is
-- structurally reconstructed from BSGO's real "Veil Sector" map (58
-- systems total) - see plan.md §2.7/§0 for why that's fair game
-- (mechanics/layout, not creative expression) while the NAMES below are
-- all real stars/star systems from our own galaxy instead of BSGO's own
-- invented system names, per the same rule that renamed Titanium/Iron/
-- Water and the ship classes. The two home systems in particular were
-- deliberately NOT given BSGO's own specific home-system names (even
-- though one of those, "Alpha Ceti", happens to itself be a real star) -
-- see plan.md §2.7 for that reasoning.
--
-- `map_x`/`map_y` are NOT meters - an abstract pixel-ish layout space,
-- same spirit as the source project's own sector_map.lua (see plan.md
-- §2.7). Calibrated against main/data/ships.lua's own ftl_range_ly (real
-- light-years, plan.md §2.1.1) via M.MAP_UNITS_PER_LY below, per direct
-- instruction ("one light-year = 35 pixels") - resolves the gap
-- main/flight_map.gui_script previously had to flag unfixed.
--
-- `width_m`/`height_m`/`depth_m` (plan.md §2.7, per direct instruction) are
-- the in-system world extent along each of the ship's own local axes (§0 -
-- Y is up, matching main/player_ship.script's own UP = (0,1,0) convention;
-- X/Z are the horizontal plane). Each defaults to `M.DEFAULT_SYSTEM_SIZE_M`
-- (10,000) when a system entry doesn't set its own - only the 3 systems
-- that actually deviate (still a uniform 40,000 cube each, matching the
-- source structure) set all three explicitly below, rather than every
-- entry repeating the same default triple 58 times.
--
-- `threat`/`threat_real` carried over as a design/balancing reference
-- only (see plan.md §0 - don't copy source numbers 1:1 as a final
-- design, treat as a starting point); `threat_real = true` marks the
-- handful the source had actual data for rather than an estimate.

local M = {}

-- Which faction's home system each of the two locked systems is -
-- mirrors the structural "two faction-exclusive home systems, everything
-- else open" pattern (plan.md §2.7), not BSGO's specific system choices.
M.HOME_SYSTEM = { accord = "sol", swarm = "polaris" }

-- Buffer zone (decided): the opposing faction also can't enter the 3
-- systems nearest each home system, not just the home system itself.
-- Computed once via M.distance from the table below (nearest-3, home
-- system itself excluded) - listed explicitly here rather than derived
-- at runtime so the restricted set is easy to read/audit directly:
--   nearest 3 to "sol"     -> wolf_359, tau_ceti, beta_andromedae
--   nearest 3 to "polaris" -> merak, ankaa, gliese_667
M.HOME_BUFFER = {
	accord = { "wolf_359", "tau_ceti", "beta_andromedae" },
	swarm  = { "merak", "ankaa", "gliese_667" },
}

function M.faction_home_of(system_id)
	for faction, home_id in pairs(M.HOME_SYSTEM) do
		if home_id == system_id then
			return faction
		end
	end
	return nil
end

-- Outposts (decided, plan.md §2.9): every one of the 58 systems has an
-- outpost for EACH faction by default - these are the in-system dock/spawn
-- points registered players return to. Exception: a faction's own home
-- system plus the 6 systems nearest to it deny the OPPOSING faction an
-- outpost entirely (that's the wider "no enemy outpost" zone - a superset
-- of M.HOME_BUFFER's narrower "can't even enter" 3-system zone above; the
-- first 3 entries of each list below are exactly M.HOME_BUFFER's own
-- systems, since nearest-3 is always a subset of nearest-6).
--   nearest 6 to "sol"     -> wolf_359, tau_ceti, beta_andromedae, epsilon_indi, avior, barnards_star
--   nearest 6 to "polaris" -> merak, ankaa, gliese_667, 70_virginis, acrux, spica
-- Keyed by the faction being DENIED an outpost, listing the systems that
-- denial applies to (that faction's opponent's home turf).
M.OUTPOST_DENIED = {
	swarm  = { "sol", "wolf_359", "tau_ceti", "beta_andromedae", "epsilon_indi", "avior", "barnards_star" },
	accord = { "polaris", "merak", "ankaa", "gliese_667", "70_virginis", "acrux", "spica" },
}

-- Does `faction` have an outpost in `system_id` at all?
function M.has_outpost(system_id, faction)
	if not M.SYSTEMS[system_id] then
		return false
	end
	local denied = M.OUTPOST_DENIED[faction]
	if denied then
		for _, id in ipairs(denied) do
			if id == system_id then
				return false
			end
		end
	end
	return true
end

-- Per-system world extent (plan.md §2.7, per direct instruction) - see this
-- file's header comment for the Y-up/X-Z-horizontal axis convention. A
-- system entry only sets width_m/height_m/depth_m when it actually deviates
-- from these defaults (currently just antares/fomalhaut/deneb).
M.DEFAULT_SYSTEM_SIZE_M = 10000

local function system_extent(sys)
	return sys.width_m or M.DEFAULT_SYSTEM_SIZE_M,
		sys.height_m or M.DEFAULT_SYSTEM_SIZE_M,
		sys.depth_m or M.DEFAULT_SYSTEM_SIZE_M
end

-- Default outpost position (decided, per direct instruction): opposite
-- diagonal corners of the system's horizontal (X/Z) extent, on the Y=0
-- plane, inset a flat M.OUTPOST_CORNER_INSET (1000 units) from each corner
-- - not a fraction of the system's size like the earlier placeholder, a
-- fixed absolute margin regardless of how big the system is. No per-system
-- position data is needed for this default case - only a system that
-- actually needs to deviate sets its own `outposts` table (below).
--
-- Explicit per-system override (new, per direct instruction: "allow for
-- coordinates for each of the outposts to be sent explicitly"): a system
-- entry's own `outposts = { accord = {x,y,z}, swarm = {x,y,z} }`, when
-- present, is returned as-is for that faction INSTEAD of the generic
-- default below - same "explicit beats computed default" precedent
-- width_m/height_m/depth_m above just established.
--
-- Returns nil if `faction` has no outpost here at all (see M.has_outpost
-- above) - checked before either the explicit or default path.
M.OUTPOST_CORNER_INSET = 1000
function M.outpost_position(system_id, faction)
	if not M.has_outpost(system_id, faction) then
		return nil
	end
	local sys = M.SYSTEMS[system_id]
	local explicit = sys.outposts and sys.outposts[faction]
	if explicit then
		return explicit
	end
	local width, _, depth = system_extent(sys)
	local offset_x = width / 2 - M.OUTPOST_CORNER_INSET
	local offset_z = depth / 2 - M.OUTPOST_CORNER_INSET
	if faction == "accord" then
		return { x = -offset_x, y = 0, z = -offset_z }
	elseif faction == "swarm" then
		return { x = offset_x, y = 0, z = offset_z }
	end
	return nil
end

-- Spawn points (decided): 2 per faction per system, spread around that
-- faction's own outpost corner rather than a single point, specifically
-- to avoid spawn-camping. Reuses the same default corner geometry as
-- M.outpost_position's own default case above (M.OUTPOST_CORNER_INSET),
-- NOT the system's literal edge, and NOT any per-system `outposts`
-- override - spawn points always follow the generic default corners
-- regardless of whether a system's actual outpost position was overridden
-- (no per-system spawn-point override exists, only for the outpost itself
-- - flag if a system's overridden outpost ever needs its spawns to follow
-- it too, plan.md §4). For a faction's own corner, the 2 points are the
-- midpoints between that corner and each of its two adjacent corners
-- (i.e. roughly the middle of each of the two nearest map edges) - NOT
-- the diagonal corner, which is the opposing faction's own outpost.
-- (Earlier draft also had a 3rd point at one of the two corners unused by
-- either outpost - removed; just the two midpoints now.)
-- Only defined where the faction actually has an outpost in this system
-- (M.has_outpost) - a faction that can enter a system WITHOUT an outpost
-- (the population-capped zone, §2.7) needs a different spawn concept
-- entirely (e.g. an FTL jump-in point) - not decided yet, see plan.md §4.
function M.spawn_points(system_id, faction)
	if not M.has_outpost(system_id, faction) then
		return nil
	end
	local sys = M.SYSTEMS[system_id]
	local width, _, depth = system_extent(sys)
	local cx = width / 2 - M.OUTPOST_CORNER_INSET
	local cz = depth / 2 - M.OUTPOST_CORNER_INSET
	if faction == "accord" then
		-- Accord's own corner: (-cx,-cz). Adjacent corners: (cx,-cz), (-cx,cz).
		return {
			{ x = 0, y = 0, z = -cz },  -- midpoint toward (cx,-cz)
			{ x = -cx, y = 0, z = 0 },  -- midpoint toward (-cx,cz)
		}
	elseif faction == "swarm" then
		-- Swarm's own corner: (cx,cz). Adjacent corners: (cx,-cz), (-cx,cz).
		return {
			{ x = cx, y = 0, z = 0 },   -- midpoint toward (cx,-cz)
			{ x = 0, y = 0, z = cz },   -- midpoint toward (-cx,cz)
		}
	end
	return nil
end

-- Opposing-ship population cap (decided, TBC): the 4th/5th/6th nearest
-- systems to each home system - the ones with no outpost for the opposing
-- faction (M.OUTPOST_DENIED above) but still enterable, unlike the
-- innermost 3 (M.HOME_BUFFER, fully blocked) - also cap how many of the
-- opposing faction's ships can be present at once. Nearest 1-3 need no cap
-- (already unenterable); the home system itself needs no cap either (same
-- reason). PLACEHOLDER value (50) - explicitly flagged by the user as not
-- final, needs real balancing (plan.md §4).
M.OPPOSING_SHIP_CAP = 50 -- TBC

M.SHIP_CAP_ZONE = {
	swarm  = { "epsilon_indi", "avior", "barnards_star" }, -- 4th-6th nearest to Sol (Accord home)
	accord = { "70_virginis", "acrux", "spica" },          -- 4th-6th nearest to Polaris (Swarm home)
}

-- The concurrent-ship cap on `faction` in `system_id`, or nil if
-- uncapped. Enforcing this (counting live ships per system) is a
-- server-side/Nakama match concern, not data - see plan.md §4.
function M.ship_cap(system_id, faction)
	local capped = M.SHIP_CAP_ZONE[faction]
	if capped then
		for _, id in ipairs(capped) do
			if id == system_id then
				return M.OPPOSING_SHIP_CAP
			end
		end
	end
	return nil
end

