-- Straight-line "map distance" between two systems, same abstract units
-- as map_x/map_y.
function M.distance(id_a, id_b)
	local a, b = M.SYSTEMS[id_a], M.SYSTEMS[id_b]
	if not a or not b then
		return nil
	end
	local dx, dy = a.map_x - b.map_x, a.map_y - b.map_y
	return math.sqrt(dx * dx + dy * dy)
end

-- Conversion factor between main/data/ships.lua's ftl_range_ly (real
-- light-years) and this file's own map_x/map_y distance scale (decided,
-- per direct instruction: "one light-year = 30 pixels"). Callers comparing
-- a ship's FTL range against M.distance()'s own output (e.g.
-- main/player_ship.script's toggle_map()/"set_jump_preset" handler) should
-- convert through M.ly_to_map_units() first - M.distance()/M.in_ftl_range()
-- themselves stay in plain map units, they don't do this conversion
-- implicitly.
M.MAP_UNITS_PER_LY = 30

function M.ly_to_map_units(ly)
	return ly * M.MAP_UNITS_PER_LY
end

-- Which faction (if any) this system is restricted to for entry purposes -
-- either it's that faction's home system, or one of the 3 systems in that
-- faction's home buffer zone (M.HOME_BUFFER above). Returns nil if the
-- system is open to both.
function M.zone_owner(system_id)
	local home = M.faction_home_of(system_id)
	if home then
		return home
	end
	for faction, buffer in pairs(M.HOME_BUFFER) do
		for _, id in ipairs(buffer) do
			if id == system_id then
				return faction
			end
		end
	end
	return nil
end

-- Can `faction` ("accord"/"swarm") ever jump into `system_id` at all?
-- Blocked if the system belongs to the OTHER faction's home system or
-- home buffer zone (M.zone_owner) - everything else is open to both.
function M.can_enter(system_id, faction)
	if not M.SYSTEMS[system_id] then
		return false
	end
	local owner = M.zone_owner(system_id)
	return owner == nil or owner == faction
end

-- Is `distance` (may be nil) within `range`?
function M.in_ftl_range(distance, range)
	if distance == nil then
		return false
	end
	return distance <= range
end

-- Every system reachable from `from_id` with `ftl_range` (map units, same
-- scale as ship_classes.lua's FTL Range stat), for `faction`, sorted
-- nearest-first. `from_id` itself is excluded.
function M.reachable_from(from_id, ftl_range, faction)
	local out = {}
	for id, _ in pairs(M.SYSTEMS) do
		if id ~= from_id and M.can_enter(id, faction) then
			local d = M.distance(from_id, id)
			if d and d <= ftl_range then
				table.insert(out, { id = id, distance = d })
			end
		end
	end
	table.sort(out, function(a, b) return a.distance < b.distance end)
	return out
end

-- Hydrogen cost of a jump (plan.md §2.6/§2.1.1's FTL Cost stat) - purely
-- `distance` rounded to a friendlier integer. Not a real balancing
-- formula yet, same "no unexplained extra constant" approach the map
-- layout itself takes - see plan.md §4 for the open TODO on real
-- yield/conversion rates.
function M.hydrogen_cost(distance)
	return math.floor(distance + 0.5)
end

return M
